import React from 'react';
import { Paper, Typography, Button, Box, Accordion, AccordionSummary, AccordionDetails } from '@mui/material';
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutline';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { useNavigate } from 'react-router-dom';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
  }

  handleReload = () => {
    window.location.reload();
  };

  handleGoHome = () => {
    this.props.navigate('/profile');
  };

  render() {
    if (this.state.hasError) {
      return (
        <div>
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              minHeight: '60vh',
              p: 3
            }}
          >
            <Paper
              elevation={3}
              sx={{
                p: 4,
                maxWidth: 500,
                textAlign: 'center',
                borderRadius: 2
              }}
            >
              <ErrorOutlineIcon
                sx={{
                  fontSize: 64,
                  color: 'warning.main',
                  mb: 2
                }}
              />
              <Typography variant="h5" gutterBottom>
                页面加载异常
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                很抱歉，当前页面遇到了一个错误。请尝试刷新页面或返回首页。
              </Typography>
              <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center', mb: 3 }}>
                <Button
                  variant="contained"
                  onClick={this.handleReload}
                >
                  刷新页面
                </Button>
                <Button
                  variant="outlined"
                  onClick={this.handleGoHome}
                >
                  返回首页
                </Button>
              </Box>
              <Accordion>
                <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                  <Typography variant="body2" color="text.secondary">
                    错误详情
                  </Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Typography variant="body2" color="error" sx={{ textAlign: 'left' }}>
                    将以下错误信息发送给管理员以协助排查：
                  </Typography>
                  <Typography
                    variant="body2"
                    sx={{
                      mt: 1,
                      p: 2,
                      bgcolor: 'grey.100',
                      borderRadius: 1,
                      fontFamily: 'monospace',
                      wordBreak: 'break-all'
                    }}
                  >
                    {this.state.error?.message || '未知错误'}
                  </Typography>
                </AccordionDetails>
              </Accordion>
            </Paper>
          </Box>
        </div>
      );
    }

    return <React.Fragment>{this.props.children}</React.Fragment>;
  }
}

export default function ErrorBoundaryWrapper(props) {
  const navigate = useNavigate();
  return <ErrorBoundary {...props} navigate={navigate} />;
}